/**
 * SQLite 마이그레이션(`db/sqlite/*.sql`, v17 원본) → Postgres 스키마(`db/marketplace.pg.sql`) 변환 (29-1).
 *
 * ## 왜 스크립트인가
 *
 * 표 30개·트리거 17개를 손으로 옮기면 한 컬럼이 조용히 빠져도 아무도 모른다. 변환을 코드로 두면
 * 원본이 바뀔 때 다시 돌릴 수 있고, 무엇을 어떻게 바꿨는지가 이 파일 하나에 적힌다.
 * 결과물이 맞는지는 이 스크립트가 아니라 **같은 통합 테스트를 Postgres에서 다시 돌려** 증명한다.
 *
 * ## 방언 차이 (여기서 처리하는 것)
 *
 * | SQLite | Postgres |
 * |---|---|
 * | `` `이름` `` | 따옴표 없이 (전부 소문자 snake_case라 충돌 없음) |
 * | `text PRIMARY KEY NOT NULL` | `text PRIMARY KEY` |
 * | `integer PRIMARY KEY AUTOINCREMENT` | `bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY` |
 * | `CREATE TRIGGER … BEGIN SELECT RAISE(ABORT,'X'); END;` | plpgsql 함수 + 트리거 (`RAISE EXCEPTION 'X'`) |
 * | `NEW.a IS NOT OLD.a` | `NEW.a IS DISTINCT FROM OLD.a` |
 * | `ALTER TABLE t ADD col` | `ALTER TABLE t ADD COLUMN col` |
 * | `instr(a,b)` | 같은 이름의 SQL 함수를 만들어 흡수한다 (앱 SQL을 고치지 않는다) |
 *
 * 예약어 `end`(calendar_events)는 이름을 바꾸지 않고 앱 SQL에서 `"end"`로 감쌌다 — 두 방언 모두 큰따옴표를
 * 식별자로 읽는다. 표 이름이 방언마다 달라지면 그때부터 두 스키마를 따로 읽어야 한다.
 */
import { readFileSync, writeFileSync } from 'node:fs'

const journal = JSON.parse(readFileSync('db/sqlite/_journal.json', 'utf8'))
const raw = journal.entries
  .map((e) => readFileSync(`db/sqlite/${e.tag}.sql`, 'utf8'))
  .join('\n')
  // drizzle이 문장 사이에 넣는 표시 — 줄 끝에 붙어 오기도 해서 먼저 전부 지운다
  .replace(/-->\s*statement-breakpoint/g, '\n')

/** `--> statement-breakpoint` 주석을 지우고 문장 단위로 나눈다 (트리거 본문의 `;`는 END; 까지 묶는다) */
function statements(sql) {
  const out = []
  let buf = ''
  let inTrigger = false
  for (const line of sql.split('\n')) {
    const t = line.trim()
    if (t === '' || t.startsWith('-->')) continue
    if (/^CREATE TRIGGER/i.test(t)) inTrigger = true
    buf += (buf === '' ? '' : '\n') + line
    if (inTrigger) {
      if (/END;\s*$/i.test(t)) {
        out.push(buf)
        buf = ''
        inTrigger = false
      }
      continue
    }
    if (t.endsWith(';')) {
      out.push(buf)
      buf = ''
    }
  }
  if (buf.trim() !== '') out.push(buf)
  return out
}

/**
 * 외래키는 표 안에 두지 않고 **맨 뒤로 모은다**. drizzle이 표를 알파벳순으로 내보내서 아직 없는 표를
 * 가리키는 줄이 나오는데, SQLite는 넘어가지만 Postgres는 그 자리에서 실패한다.
 */
const foreignKeys = []

/** Postgres 예약어라 그냥 두면 문법 오류가 나는 컬럼 — 앱 SQL도 같은 모양(`"end"`)으로 쓴다 */
const RESERVED = ['end']

function convertTable(sql) {
  let out = sql.replace(/`/g, '')
  for (const word of RESERVED) out = out.replace(new RegExp(`^(\\s*)${word}( )`, 'gm'), `$1"${word}"$2`)
  out = out.replace(
    /integer PRIMARY KEY AUTOINCREMENT NOT NULL/gi,
    'integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY',
  )
  out = out.replace(/(\w+) text PRIMARY KEY NOT NULL/gi, '$1 text PRIMARY KEY')
  out = out.replace(/ON UPDATE no action ON DELETE no action/gi, '')
  const table = out.match(/CREATE TABLE (\w+)/i)?.[1]
  if (table !== undefined) {
    let n = 0
    out = out
      .split('\n')
      .filter((line) => {
        const fk = line.trim().replace(/,$/, '').trim()
        if (!/^FOREIGN KEY/i.test(fk)) return true
        n += 1
        // 29-5: 다시 돌려도 되게 감싼다 — Postgres에는 ADD CONSTRAINT IF NOT EXISTS가 없다
        foreignKeys.push(
          [
            `DO $$ BEGIN`,
            `  ALTER TABLE ${table} ADD CONSTRAINT ${table}_fk${n} ${fk};`,
            `EXCEPTION WHEN duplicate_object THEN NULL; END $$;`,
          ].join('\n'),
        )
        return false
      })
      .join('\n')
    // 외래키 줄을 빼면서 남은 쉼표를 정리한다
    out = out.replace(/,(\s*)\)/g, '$1)')
  }
  return out
}

/** `CREATE TRIGGER n BEFORE EV [OF cols] ON t [WHEN cond] BEGIN SELECT RAISE(ABORT,'MSG'); END;` */
function convertTrigger(sql) {
  const flat = sql.replace(/`/g, '').replace(/\s+/g, ' ').trim()
  const head = flat.match(/^CREATE TRIGGER (\w+) BEFORE (INSERT|UPDATE|DELETE)(?: OF ([\w, ]+?))? ON (\w+)/i)
  if (!head) throw new Error(`트리거를 해석하지 못했습니다: ${flat.slice(0, 120)}`)
  const [, name, event, cols, table] = head
  const when = flat.match(/ WHEN (.+?) BEGIN /i)?.[1] ?? null
  const message = flat.match(/RAISE\(ABORT,\s*'([^']+)'\)/i)?.[1]
  if (message === undefined) throw new Error(`RAISE 메시지를 찾지 못했습니다: ${name}`)
  const cond = when === null ? 'TRUE' : when.replace(/ IS NOT OLD\./gi, ' IS DISTINCT FROM OLD.')
  const ret = event.toUpperCase() === 'DELETE' ? 'OLD' : 'NEW'
  const of = cols ? ` OF ${cols.trim()}` : ''
  return [
    `CREATE OR REPLACE FUNCTION ${name}_fn() RETURNS trigger AS $$`,
    `BEGIN`,
    `  IF ${cond} THEN RAISE EXCEPTION '${message}'; END IF;`,
    `  RETURN ${ret};`,
    `END;`,
    `$$ LANGUAGE plpgsql;`,
    `DROP TRIGGER IF EXISTS ${name} ON ${table};`,
    `CREATE TRIGGER ${name} BEFORE ${event.toUpperCase()}${of} ON ${table} FOR EACH ROW EXECUTE FUNCTION ${name}_fn();`,
  ].join('\n')
}

/**
 * 29-5: **다시 돌려도 되는 스키마로 만든다.**
 *
 * db/schema.sql은 처음부터 멱등했는데(주석에 그렇게 적혀 있다) 이쪽은 아니었다 — 표 30개가
 * 맨 CREATE TABLE이라 두 번째 적용이 곧 오류였다. 그래서 배포할 때 사람이 "처음인가 아닌가"를
 * 알고 있어야 했다. 트리거·함수는 이미 DROP IF EXISTS와 CREATE OR REPLACE로 그 성질을 갖고 있었으니
 * 표·인덱스·컬럼도 같은 자리에 맞춘다. 그래야 서버가 뜰 때 스스로 적용할 수 있다.
 */
function idempotent(sql) {
  return sql
    .replace(/^CREATE TABLE (?!IF NOT EXISTS)/gim, 'CREATE TABLE IF NOT EXISTS ')
    .replace(/^CREATE INDEX (?!IF NOT EXISTS)/gim, 'CREATE INDEX IF NOT EXISTS ')
    .replace(/^CREATE UNIQUE INDEX (?!IF NOT EXISTS)/gim, 'CREATE UNIQUE INDEX IF NOT EXISTS ')
    .replace(/ADD COLUMN (?!IF NOT EXISTS)/gi, 'ADD COLUMN IF NOT EXISTS ')
}

const converted = []
for (const stmt of statements(raw)) {
  const kind = stmt.trim().slice(0, 20).toUpperCase()
  if (kind.startsWith('CREATE TRIGGER')) converted.push(convertTrigger(stmt))
  else if (kind.startsWith('DROP TRIGGER')) {
    const name = stmt.match(/DROP TRIGGER (\w+)/i)[1]
    // 어느 표에 걸렸는지는 앞의 CREATE에서 안다 — photo_limit 하나뿐이라 표를 직접 적는다
    converted.push(`DROP TRIGGER IF EXISTS ${name} ON photos;\nDROP FUNCTION IF EXISTS ${name}_fn();`)
  } else if (/^ALTER TABLE/i.test(stmt.trim())) {
    converted.push(convertTable(stmt).replace(/ADD (\w+)/i, 'ADD COLUMN $1'))
  } else converted.push(convertTable(stmt))
}

const header = `-- 자동 생성 (scripts/pg-schema.mjs) — 직접 고치지 말고 스크립트를 고쳐 다시 만드세요.
-- 원본: db/sqlite/*.sql (v17 drizzle 마이그레이션, SQLite). 검증: 같은 통합 테스트를 이 스키마 위에서 다시 돌린다.

-- SQLite에만 있는 instr()를 같은 이름으로 만들어 둔다 — 앱 SQL 한 벌이 두 방언에서 그대로 돌게 하는 값싼 방법이다.
-- SQLite의 max(a,b)는 **스칼라**다. Postgres의 max는 집계 함수라 인자가 하나뿐이어서 그대로는 깨진다.
-- instr과 같은 방법으로 흡수한다: 같은 이름의 2인자 함수를 만든다(집계와 인자 수로 구분되어 충돌하지 않는다).
-- 앱 SQL을 고치지 않아야 원본과 대조할 수 있다.
CREATE OR REPLACE FUNCTION max(a bigint, b bigint) RETURNS bigint AS $fn$
  SELECT GREATEST(a, b);
$fn$ LANGUAGE sql IMMUTABLE;

CREATE OR REPLACE FUNCTION instr(haystack text, needle text) RETURNS integer AS $fn$
  SELECT strpos(haystack, needle);
$fn$ LANGUAGE sql IMMUTABLE;
`
const all = [...converted.map(idempotent), '', '-- 외래키 (표를 전부 만든 뒤에 건다)', ...foreignKeys]
const marketplaceSql = `${header}\n${all.join('\n')}\n`
writeFileSync('db/marketplace.pg.sql', marketplaceSql)

/**
 * 29-5: 서버가 **자기 스키마를 스스로 적용**할 수 있게 같은 내용을 모듈로도 낸다.
 *
 * 서버리스에서는 배포 번들에 .sql 파일이 함께 들어간다는 보장이 없다. 실행 시점에 파일을 읽는 대신
 * 문자열로 박아 두면 그 불확실성이 사라진다. 파일과 모듈이 어긋나지 않는지는
 * server/schemaBootstrap.test.ts 가 본다.
 */
const baseSql = readFileSync('db/schema.sql', 'utf8')
writeFileSync(
  'db/schema.generated.ts',
  [
    '// 자동 생성 (scripts/pg-schema.mjs) — 직접 고치지 마세요. `npm run db:pg-schema`로 다시 만듭니다.',
    '// db/schema.sql 과 db/marketplace.pg.sql 의 내용을 그대로 담습니다 (서버가 스스로 적용할 때 씁니다).',
    '',
    `export const BASE_SQL = ${JSON.stringify(baseSql)}`,
    '',
    `export const MARKETPLACE_SQL = ${JSON.stringify(marketplaceSql)}`,
    '',
  ].join('\n'),
)
console.log(
  `문장 ${converted.length}개 + 외래키 ${foreignKeys.length}개 → db/marketplace.pg.sql · db/schema.generated.ts`,
)
